const input = $input.first().json;
const get = (label) => {
  if (input[label] !== undefined) return input[label];
  const key = Object.keys(input).find((k) => k.trim().toLowerCase() === label.trim().toLowerCase());
  return key ? input[key] : '';
};
const freq = (v) => ({'Nunca':0,'Raramente':1,'Às vezes':2,'Frequentemente':3,'Quase sempre':4}[String(v)] ?? 0);
const func = (v) => ({'Nunca':0,'Raramente':1,'Às vezes':1,'Frequentemente':2,'Quase sempre':2}[String(v)] ?? 0);
const sleepScore = (v) => ({'Muito tranquilo':0,'Levemente agitado':1,'Acorda ocasionalmente':1,'Sono agitado':2,'Acorda várias vezes':2}[String(v)] ?? 0);
const mordidaScore = (v) => ({'Sim, já foi identificado':2,'Suspeito mas nunca avaliado':1,'Nunca reparei':0,'Não sei':0}[String(v)] ?? 0);
const dentesScore = (v) => ({'Não':0,'Leve':1,'Moderado':2,'Acentuado':2}[String(v)] ?? 0);
const habitoScore = (v) => ({'Sim':2,'Não':0,'Não sei':0}[String(v)] ?? 0);
const labels = {
  child: 'Nome da criança', age: 'Qual a idade?', responsible: 'Qual é o seu nome?', whatsapp: 'Qual é o seu número de WhatsApp?',
  q5: 'Observa a boca aberta em repouso (sem estar a falar ou a comer)?', q6: 'Tem dificuldade em respirar pelo nariz mesmo quando não está constipado?', q7: 'Ressona durante o sono?', q8: 'Costuma babar na almofada durante a noite?', q9: 'Os lábios ficam frequentemente secos ou gretados?', q10: 'Desde pequeno(a), teve frequentemente nariz entupido, alergias respiratórias ou problemas de adenóides?', q11: 'Como descreveria o sono da criança?', q12: 'Já reparou se fala com a língua entre os dentes ou tem dificuldade em alguns sons?', q13: 'Observa tendência para cabeça projetada para a frente ou ombros curvados?', q14: 'Já lhe disseram que a criança tem mordida cruzada, aberta ou que os dentes não encaixam bem?', q15: 'Os dentes estão muito apinhados ou muito espaçados?', q16: 'Usou chucha ou chupou no dedo por período prolongado (após os 3 anos)?'
};
const answers = Object.fromEntries(Object.entries(labels).map(([k,l]) => [k, get(l)]));
const scoreA = ['q5','q6','q7','q8','q9','q10'].reduce((s,k) => s + freq(answers[k]), 0);
const scoreB = sleepScore(answers.q11) + func(answers.q12) + func(answers.q13);
const scoreC = mordidaScore(answers.q14) + dentesScore(answers.q15) + habitoScore(answers.q16);
const totalScore = scoreA + scoreB + scoreC;
const riskLevel = totalScore <= 12 ? 'nasal' : totalScore <= 24 ? 'suspeito' : 'elevado';
const facts = `Boca aberta em repouso: ${answers.q5}
Dificuldade em respirar pelo nariz (fora constipações): ${answers.q6}
Ronco: ${answers.q7}
Baba na almofada: ${answers.q8}
Lábios secos/gretados: ${answers.q9}
Histórico de nariz entupido/alergias/adenóides: ${answers.q10}
Qualidade do sono: ${answers.q11}
Fala/língua entre dentes: ${answers.q12}
Postura (cabeça/ombros): ${answers.q13}
Mordida/encaixe: ${answers.q14}
Alinhamento dentário: ${answers.q15}
Hábitos orais prolongados (chucha/dedo após 3 anos): ${answers.q16}`;
const reportPrompt = `Escreva um relatório educativo e personalizado em português de Portugal com base exclusivamente no bloco factual abaixo. Não faça diagnóstico, não invente sintomas, não altere frequências e não omita sinais Frequentes ou Quase sempre. Explique os sinais em conjunto, respiração nasal versus oral, relação com desenvolvimento craniofacial, sono e dia a dia, relevância da idade, o que será avaliado em consulta e conclua com recomendação acolhedora de avaliação presencial. Use 800 a 1000 palavras. Não use: urgente, grave, severo, certeza, garantia, diagnóstico definitivo.

BLOCO FACTUAL:
${facts}

Classificação interna: ${riskLevel}
Faixa etária: ${answers.age}
Nome da criança: ${answers.child}`;
return [{json:{...input, childName:answers.child, age:answers.age, responsibleName:answers.responsible, whatsapp:answers.whatsapp, scoreA, scoreB, scoreC, totalScore, riskLevel, facts_block_ptpt:facts, reportPrompt}}];
